\begin{itemchoice}
			\itemch Hộp I ban đầu có tổng cộng $5$ viên bi, trong đó có $3$ viên bi xanh. Xác suất để lấy được $1$ viên bi xanh từ hộp I là: $P(A) = \displaystyle\frac{3}{5}$.
			\itemch Khi biến cố $A$ xảy ra, hộp II nhận thêm $1$ bi xanh, dẫn đến số bi trong hộp II lúc này gồm: $5$ bi xanh và $1$ bi đỏ (tổng cộng có $6$ viên bi). Xác suất lấy được bi đỏ từ hộp II khi đó là: $P(\overline{B} \mid A) = \displaystyle\frac{1}{6}$.
			\itemch Xác suất lấy được bi đỏ từ hộp I ban đầu là: $P(\overline{A}) = \displaystyle\frac{2}{5}$.\\ Khi biến cố $\overline{A}$ xảy ra, hộp II nhận thêm $1$ bi đỏ, dẫn đến số bi trong hộp II lúc này gồm: $4$ bi xanh và $2$ bi đỏ (tổng cộng có $6$ viên bi).\\ Xác suất lấy được bi xanh từ hộp II khi đó là: $P(B \mid \overline{A}) = \displaystyle\frac{4}{6} = \frac{2}{3}$.
			\itemch Áp dụng công thức xác suất toàn phần, ta có:\\ $P(\overline{B}) = P(A)P(\overline{B} \mid A) + P(\overline{A})P(\overline{B} \mid \overline{A}) = \displaystyle\frac{3}{5} \cdot \frac{1}{6} + \frac{2}{5} \cdot \frac{2}{6} = \frac{7}{30}$.\\ Bên cạnh đó, $P(A\overline{B}) = P(A) \cdot P(\overline{B} \mid A) = \displaystyle\frac{3}{5} \cdot \frac{1}{6} = \frac{3}{30} = \frac{1}{10}$.\\ Như vậy, $P(A \mid \overline{B}) = \displaystyle\frac{P(A\overline{B})}{P(\overline{B})} = \frac{\displaystyle\frac{3}{30}}{\displaystyle\frac{7}{30}} = \frac{3}{7}$.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Ta có: $f\left(\displaystyle\frac{1}{e^2}\right) = \displaystyle\frac{1}{e^2} \ln\left(e^{-2}\right) = -\frac{2}{e^2}$. Và $f(e) = e \ln e = e$.
			\itemch Ta có: $f'(x) = (x \ln x)' = \ln x + x \cdot \displaystyle\frac{1}{x} = \ln x + 1$.
			\itemch Ta có $f'(x) = 0 \Leftrightarrow \ln x + 1 = 0 \Leftrightarrow x = \displaystyle\frac{1}{e} \in \left[e^{-2}; e\right]$.
			\itemch Ta có: $f(e^{-2}) = -\displaystyle\frac{2}{e^2}$; $f(e^{-1}) = -\displaystyle\frac{1}{e}$; $f(e) = e$.\\ Vậy giá trị nhỏ nhất của $f(x)$ trên đoạn $\left[e^{-2}; e\right]$ là $-\displaystyle\frac{1}{e}$.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Ta có: $\overrightarrow{AB} = (8-2;0-0;4-4) = (6;0;0)$; $\overrightarrow{AC} = (5-2;6-0;7-4) = (3;6;3)$.
			\itemch Mặt phẳng $(ABC)$ đi qua $3$ điểm $A$, $B$, $C$ nên sẽ nhận $\overrightarrow{AB}$ và $\overrightarrow{AC}$ làm cặp vectơ chỉ phương.\\ Một vectơ pháp tuyến của mặt phẳng $(ABC)$ là $\left[\overrightarrow{AB}, \overrightarrow{AC}\right] = (0;-18;36) = -18(0;1;-2) \Rightarrow \vec{n} = (0;1;-2)$.
			\itemch Mặt phẳng mái nhà chính là mặt phẳng $(ABC)$. Mặt phẳng này đi qua điểm $A(2;0;4)$ và có vectơ pháp tuyến $\vec{n} = (0;1;-2)$ vừa tìm được ở ý trên.\\ Phương trình tổng quát của mặt phẳng $(ABC)$ được viết như sau: $0(x-2) + 1(y-0) - 2(z-4) = 0 \Leftrightarrow y - 2z + 8 = 0$.
			\itemch Để kiểm tra vị trí camera có đạt chuẩn hay không, ta tính khoảng cách từ điểm đặt camera $M(5;7;8)$ đến mặt phẳng mái nhà $(ABC)$ có phương trình $y - 2z + 8 = 0$:\\ $d(M, (ABC)) = \displaystyle\frac{|y_M - 2z_M + 8|}{\sqrt{0^2 + 1^2 + (-2)^2}} = \frac{|7 - 2 \cdot 8 + 8|}{\sqrt{1+4}} = \frac{|7-16+8|}{\sqrt{5}} = \frac{|-1|}{\sqrt{5}} = \frac{1}{\sqrt{5}} \approx 0{,}447\text{ m}$.\\ Khoảng cách này nhỏ hơn $0{,}5\text{ m}$ nên không đáp ứng đúng quy chuẩn.
		\end{itemchoice}

\begin{itemchoice}
			\itemch $v(10) = 100 + 20 \cdot 10 - 10^2 = 200\text{ m}^3/\text{phút}$.
			\itemch Tổng lượng nước thêm vào bể sau $15$ phút là $Q = \displaystyle\int_0^{15} v(t) \,dt = \int_0^{15} (-t^2 + 20t + 100) \,dt$.
			\itemch Tốc độ thay đổi lượng nước trong bể là $f(t) = v(t) - 150 = (100 + 20t - t^2) - 150 = -t^2 + 20t - 50$.
			\itemch Lượng nước trong bể tại thời điểm $t$ được tính bằng lượng nước ban đầu cộng tổng lượng nước thay đổi từ $0$ đến $t$:\\ $V(t) = V_0 + \displaystyle\int_0^t f(x) \,dx = 650 + \int_0^t (-x^2 + 20x - 50) \,dx \Rightarrow V(t) = -\frac{t^3}{3} + 10t^2 - 50t + 650$.\\ Suy ra $V'(t) = -t^2 + 20t - 50$. Cho $V'(t) = 0 \Leftrightarrow -t^2 + 20t - 50 = 0 \Leftrightarrow t_1 = 10 - 5\sqrt{2} = a$ hoặc $t_2 = 10 + 5\sqrt{2} = b$.\\ Bảng biến thiên:
			\begin{center}
				<img src='HinhAnh/sol_88ad1e167c_lg_tikz_1.png' style='max-width: 400px; height: auto; display: block; margin: 10px auto;' />
			\end{center}
			Từ bảng biến thiên suy ra tại $t_2 = 10 + 5\sqrt{2} < 25 \Rightarrow V > 1000$.\\ Suy ra bể bị tràn nước khi trước $25$ phút.
		\end{itemchoice}
